import {openDialog,closeDialog,ownsDialog,environment,jsonRequest} from './ui-core.mjs';
import {integrations,definition,validateConfig,envFile,workflowTemplate} from './integration-core.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let sharedSession=null;
let key='',mode='draft',snapshots=[],drafts={},canSave=false,canManage=false,epoch=0;
export function integrationsPage(){return '<section id="integrations-root" aria-label="接入中心"></section>'}
export function clearIntegrationsSession(){sharedSession=null;key='';snapshots=[];drafts={};canSave=canManage=false;epoch++;}
export function bindIntegrations(shared=null){sharedSession=shared;if(shared){key=shared.key;mode='server'}const root=document.querySelector('#integrations-root');if(root)mount(root)}
async function api(path,method='GET',data){return jsonRequest(path,{method,headers:{authorization:'Bearer '+key,'content-type':'application/json'},body:data?JSON.stringify(data):undefined,cache:'no-store'},'当前网址仅托管前端，不能保存服务端配置。请在自部署的 AgentGuard 网页中连接，或使用“编辑部署配置”下载 .env。')}
function download(name,text){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function mount(root){const ticket=++epoch;environment(mode==='server'?(key?'接入配置 · 正在校验':'接入配置 · 未连接'):'接入配置 · 未部署',mode==='server'?'校验成功后才可管理真实服务':'草稿仅在内存 · 不执行外部调用');root.innerHTML=`<div class="heading"><div><h1>接入中心</h1><p>编辑模型、工作流和告警配置，再验证实际连接状态。</p></div><a class="button" href="DEPLOY.html" target="_blank" rel="noopener">部署说明 ↗</a></div><div class="usage-toolbar"><div class="usage-tabs"><button data-integrations-mode="draft" aria-pressed="${mode==='draft'}">编辑部署配置</button><button data-integrations-mode="server" aria-pressed="${mode==='server'}">管理服务端连接</button></div></div><div class="note">${mode==='draft'?'此模式可编辑并下载 .env 配置片段；内容仅在本页内存中，刷新后清除。填写或下载不代表已连接。':'连接当前网页同源的 AgentGuard 后端。ADMIN_KEY 可保存和检测，READ_KEY 仅查看。密钥不回显、不保存在浏览器存储。'}</div><div id="integration-auth"></div><div id="integration-message" role="status"></div><div id="integration-cards"></div>`;
 if(sharedSession)root.querySelector('[data-integrations-mode]')?.parentElement.remove();
 const $=s=>root.querySelector(s);root.querySelectorAll('[data-integrations-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.integrationsMode;key='';snapshots=[];mount(root)});
 if(mode==='draft'){renderCards(root,ticket);return}
 $('#integration-auth').innerHTML=key?'<div class="usage-toolbar"><span>同源连接 · 凭证仅在内存</span><div class="actions"><button class="button" data-integration-refresh>刷新状态</button><button class="button" data-integration-disconnect>断开</button></div></div>':'<form id="integration-login" class="usage-login"><label>服务端访问密钥<input name="key" type="password" autocomplete="off" placeholder="ADMIN_KEY 或 READ_KEY" required></label><button class="button primary">连接服务端</button><small>如果当前是在线预览，请先下载部署配置，在本机或私有服务器启动后端。</small></form>';
 if(!key){$('#integration-login').onsubmit=e=>{e.preventDefault();key=new FormData(e.target).get('key');mount(root)};return}
 $('[data-integration-disconnect]').onclick=()=>{if(sharedSession)return sharedSession.onLogout();key='';snapshots=[];mount(root)};$('[data-integration-refresh]').onclick=()=>mount(root);
 $('#integration-cards').innerHTML='<div class="empty">正在读取配置…</div>';
 api('/api/integrations').then(data=>{if(ticket!==epoch||!root.isConnected)return;snapshots=data.integrations;canSave=data.canSave;canManage=data.canManage;environment(canManage?'接入配置 · 管理员':'接入配置 · 只读','连接已验证 · 配置作用于真实服务');renderCards(root,ticket);if(!canSave)$('#integration-message').textContent='服务端未配置加密密钥，暂不能保存。请设置 CONFIG_ENCRYPTION_KEY 后重启服务，详见部署说明。'}).catch(e=>{if(ticket===epoch&&root.isConnected){environment('接入配置 · 连接失败','检查密钥与同源服务');$('#integration-message').textContent=e.message;$('#integration-cards').innerHTML=''}})
}
function renderCards(root,ticket){const cards=root.querySelector('#integration-cards');cards.innerHTML=`<div class="section-title">模型供应商</div><div class="cards3">${integrations.filter(x=>x.type==='provider').map(card).join('')}</div><div class="section-title">编码工具</div><div class="cards3">${['Claude Code','Codex'].map(name=>`<section class="card integration"><div class="monogram">${name==='Codex'?'Cx':'Cc'}</div><h3>${name}</h3><p>创建遥测连接，配置预算和本机启动器。</p><a class="button" href="#coding">创建 / 管理连接 →</a></section>`).join('')}</div><div class="section-title">工作流平台 · HTTP 节点配置</div><div class="cards3">${['Dify','Coze','n8n'].map(name=>`<section class="card integration"><div class="monogram">${name.slice(0,2)}</div><h3>${name} <span class="badge">HTTP 配置</span></h3><p>编辑服务地址、任务与费用归属，生成节点配置后到平台添加。</p><button class="button" data-workflow="${name}">编辑节点配置</button></section>`).join('')}</div><div class="section-title">告警渠道</div><div class="cards3">${integrations.filter(x=>x.type==='notification').map(card).join('')}</div>`;
 root.querySelectorAll('[data-integration-edit]').forEach(b=>b.onclick=()=>edit(root,b.dataset.integrationEdit,ticket));root.querySelectorAll('[data-workflow]').forEach(b=>b.onclick=()=>workflow(b.dataset.workflow));
}
function card(def){const saved=snapshots.find(x=>x.id===def.id),draft=drafts[def.id],status=mode==='draft'?(draft?'草稿 · 未部署':'待配置'):saved?.error?'配置锁定':saved?.origin==='database'&&!saved.enabled?'已停用':saved?.enabled?(saved.verification?.ok?'检测通过':saved.verification?'检测未通过':saved.origin==='database'?'已保存 · 未检测':'环境配置 · 未检测'):'待配置';return `<section class="card integration"><div class="integration-card-top"><div class="monogram">${esc(def.name.slice(0,2))}</div><span class="badge ${saved?.verification?.ok?'running':''}">${status}</span></div><h3>${def.name}</h3><p>${def.type==='provider'?'填写 API 地址、模型、密钥和单价。备用模型可选。':'填写机器人 Webhook。保存后可发送测试告警。'}</p>${mode==='server'&&saved?.verification?`<small class="integration-evidence">${esc(saved.verification.message)}</small>`:''}<button class="button ${mode==='draft'||canManage?'primary':''}" data-integration-edit="${def.id}">${mode==='server'&&!canManage?'查看配置':'编辑配置'}</button></section>`}

function edit(root,id,ticket){const def=definition(id),server=mode==='server',snapshot=server?snapshots.find(x=>x.id===id):null,source=server?snapshot?.values||{}:drafts[id]?.values||{},hasSecret=server?snapshot?.hasSecret||{}:{},readonly=server&&!canManage;
 const dialog=openDialog(`<h2>${def.name} · 编辑配置</h2><p>${server?'保存后即时生效。已保存的密钥留空表示保留；勾选清除可删除。':'编辑后可暂存本页草稿或下载 .env 配置片段。此模式不会调用供应商接口。'}</p><form id="integration-form"><div class="integration-form-grid">${def.fields.map(f=>`<label>${f.label}${f.required?' <span class="required">*</span>':''}<input name="${f.key}" type="${f.secret?'password':f.number?'number':'text'}" ${f.number?'min="0" step="any"':''} value="${esc(source[f.key]??'')}" placeholder="${hasSecret[f.key]?'已保存，留空保留':esc(f.placeholder||'')}" autocomplete="off" ${readonly?'disabled':''}>${f.secret&&hasSecret[f.key]?`<span class="secret-clear"><input type="checkbox" name="clear-${f.key}" ${readonly?'disabled':''}> 清除已保存的值</span>`:''}</label>`).join('')}</div><label class="integration-toggle"><input type="checkbox" name="enabled" ${server?(snapshot?.enabled?'checked':''):(drafts[id]?.enabled===false?'':'checked')} ${readonly?'disabled':''}> 启用${def.type==='provider'?'模型代理':'告警渠道'}</label><div class="note">${def.type==='provider'?'单价需按供应商实际计费填写。检测只读取模型列表，不发起付费生成请求，也不验证最终账单。':'发送测试告警会向已保存的 Webhook 发送一条 AgentGuard 测试消息。'}</div><div id="integration-editor-status" role="status"></div><div class="actions integration-form-actions">${!server?'<button class="button primary" type="submit">暂存本页草稿</button><button class="button" type="button" data-env-export>下载 .env（Node）</button><button class="button" type="button" data-docker-env-export>下载 .env（Docker）</button>':`<button class="button primary" type="submit" ${!canSave||readonly?'disabled':''}>保存到服务端</button><button class="button" type="button" data-integration-test ${readonly||!snapshot?.enabled?'disabled':''}>${def.type==='provider'?'检查模型列表':'发送测试告警'}</button>`}<button class="button" type="button" data-editor-cancel>取消</button></div>${server&&!canSave?'<p class="usage-caption">服务端需要设置 CONFIG_ENCRYPTION_KEY 才能加密保存。环境变量配置仍可读取。</p>':''}</form>`);
 const form=dialog.querySelector('form'),message=text=>{const el=form.querySelector('#integration-editor-status');if(ownsDialog(form)&&el)el.textContent=text};let dirty=false;
 const collect=()=>{const data=new FormData(form),values=Object.fromEntries(def.fields.map(f=>[f.key,data.get(f.key)||''])),clearSecrets=def.fields.filter(f=>form.querySelector('[name="clear-'+f.key+'"]')?.checked).map(f=>f.key),enabled=form.querySelector('[name="enabled"]').checked;return{values:validateConfig(id,values,{complete:server&&enabled,hasSecret:Object.fromEntries(Object.entries(hasSecret).filter(([k])=>!clearSecrets.includes(k)))}),clearSecrets,enabled,revision:snapshot?.revision||0}};
 form.oninput=()=>{dirty=true;const test=form.querySelector('[data-integration-test]');if(test)test.disabled=true;message(server?'有未保存修改，请先保存再检测。':'草稿尚未暂存。')};
 form.querySelector('[data-editor-cancel]').onclick=()=>closeDialog();
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;try{const b=collect();if(!server){drafts[id]=b;closeDialog();renderCards(root,ticket);return}const updated=await api('/api/integrations/'+id,'PUT',b);if(ticket!==epoch||!root.isConnected)return;snapshots=snapshots.map(x=>x.id===id?updated:x);if(ownsDialog(form))closeDialog();renderCards(root,ticket);root.querySelector('#integration-message').textContent=def.name+' 配置已保存并即时生效，尚未检测。';}catch(e){message(e.message)}finally{button.disabled=server&&(!canSave||readonly)}};
 const exportConfig=format=>{try{const b=collect();if(!b.enabled)throw Error('停用状态不导出密钥。请在服务端保存“停用”，或从 .env 移除该供应商配置。');download('agentguard-'+id.toLowerCase()+(format==='docker'?'.docker':'')+'.env',envFile(id,b.values,format));message('已下载 '+(format==='docker'?'Docker --env-file':'Node --env-file')+' 配置片段。请按对应运行方式使用；可能包含密钥，不要提交到 Git。')}catch(e){message(e.message)}};
 const exportButton=form.querySelector('[data-env-export]');if(exportButton)exportButton.onclick=()=>exportConfig('dotenv');const dockerExport=form.querySelector('[data-docker-env-export]');if(dockerExport)dockerExport.onclick=()=>exportConfig('docker');
 const testButton=form.querySelector('[data-integration-test]');if(testButton)testButton.onclick=async()=>{if(testButton.disabled)return;if(dirty)return message('请先保存修改');testButton.disabled=true;try{const result=await api('/api/integrations/'+id+'/test','POST',{confirm:true});if(ticket!==epoch||!ownsDialog(form)||!root.isConnected)return;message(result.message);const data=await api('/api/integrations');if(ticket!==epoch||!root.isConnected)return;snapshots=data.integrations;renderCards(root,ticket)}catch(e){message(e.message)}finally{testButton.disabled=dirty||readonly||!snapshot?.enabled}};
}
function workflow(platform){const dialog=openDialog(`<h2>${platform} · 编辑 HTTP 节点配置</h2><p>生成通用节点配置，再到 ${platform} 中添加 HTTP 请求和条件节点。这里不会自动修改平台。</p><form id="workflow-form"><div class="integration-form-grid"><label>AgentGuard 服务地址<input name="url" value="http://127.0.0.1:8080" required></label><label>任务 ID<input name="task" value="run-001" required></label><label>客户<input name="customer" value="内部团队"></label><label>产品功能<input name="feature" value="工作流"></label><label>策略<select name="policy"><option value="research">研究智能体</option><option value="support">客服智能体</option><option value="content">内容智能体</option></select></label></div><p class="usage-caption">云端平台需能访问你的服务地址；localhost 指向平台自身。INGEST_KEY 请放在平台密钥变量中，不在本页填写。</p><button class="button primary" type="submit">生成并下载节点配置</button><div id="workflow-status" role="status"></div><pre id="workflow-preview" class="coding-code" hidden></pre></form>`);const form=dialog.querySelector('form');form.onsubmit=e=>{e.preventDefault();try{const f=new FormData(form),data=workflowTemplate(platform,Object.fromEntries(['url','task','customer','feature','policy'].map(k=>[k,f.get(k)]))),text=JSON.stringify(data,null,2);dialog.querySelector('#workflow-preview').textContent=text;dialog.querySelector('#workflow-preview').hidden=false;download('agentguard-'+platform.toLowerCase()+'-http.json',text);dialog.querySelector('#workflow-status').textContent='已生成配置。请在平台逐一配置节点，并设置 stop / approval 分支停止。'}catch(e){dialog.querySelector('#workflow-status').textContent=e.message}}}
